import { convertToStructuredMessage } from "./coder/conversations.ts";

export type Author = "user" | "model" | "system";

export type Message = {
  id: string;
  content: string;
  timestamp: number;
  author: Author;
};

export const DATE_TIME_FORMAT = new Intl.DateTimeFormat("en-UK", {
  day: "numeric",
  month: "numeric",
  year: "numeric",
  hour: "numeric",
  minute: "numeric",
});

export const SYSTEM_PROMPT = convertToStructuredMessage(
  "system",
  `You are an AI model embedded in a custom harness. You are running on the users machine.

You will encounter system, model and author prompts. System prompts result from tool callings or general context,
model prompts are from you, and user prompts are directly from the user.

Tool calls are possible. To know which tools are available, use the "list-tools" tool. Any tool you want to invoke
must be specified by the "list-tools" tool, otherwise it is not present. To invoke a tool, write use json syntax
of the form {"tool":<tool-id>,"args":<args>} where <args> is a string of a specific syntax specified by the tool.
The object should be as trimmed as possible, no unnecessary whitespaces. Every tool call from you must be wrapped within
a leading and following new line, aka \n<tool-call>\n.
`,
);

import { filterConversationFor } from "./coder/conversations.ts";
import { Logger } from "./coder/logger.ts";
import {
  GEMINI_3_1_FLASH_LITE_PREVIEW,
  GEMINI_3_1_PRO_PREVIEW,
} from "./harness/models.ts";
import { Session } from "./harness/session.ts";

const session = new Session(GEMINI_3_1_PRO_PREVIEW);

const decoder = new TextDecoder();
for await (const chunk of Deno.stdin.readable) {
  const text = decoder.decode(chunk);

  const responses = await session.prompt(text);
  if (responses.length === 0) {
    console.warn("model didn't answer :/");
    continue;
  }

  Logger.logConversation(filterConversationFor("model", responses));
}

import { Message } from "../constants.ts";

export function convertToStructuredMessage(
  author: Message["author"],
  content: string,
  timestamp = Date.now(),
): Message {
  const id = crypto.randomUUID();

  return {
    id,
    content,
    author,
    timestamp,
  };
}

export function filterConversationFor(
  author: Message["author"],
  conversation: Message[],
): Message[] {
  return conversation.filter((message) => message.author === author);
}

import { DATE_TIME_FORMAT, Message } from "../constants.ts";

export class Logger {
  private static prepareMessage(
    message: Message,
    annotate = false,
  ): string {
    const author = annotate ? `%c${message.author}%c` : message.author;

    const formattedTimestamp = DATE_TIME_FORMAT.format(
      new Date(message.timestamp),
    );

    const timestamp = annotate
      ? `%c${formattedTimestamp}%c`
      : formattedTimestamp;

    return `[${author} wrote at ${timestamp}]:\n${message.content}`;
  }

  static stringifyMessage(message: Message): string {
    return Logger.prepareMessage(message);
  }

  static stringifyConversation(conversation: Message[]): string {
    return conversation.map((message) => Logger.stringifyMessage(message)).join(
      "\n\n",
    );
  }

  static logMessage(message: Message): void {
    const formatted = Logger.prepareMessage(message, true);

    console.log(
      formatted,
      "color: red",
      "color: unset",
      "color: blue",
      "color: unset",
    );
  }

  static logConversation(conversation: Message[]): void {
    for (const message of conversation) {
      Logger.logMessage(message);
    }
  }
}

import { DATE_TIME_FORMAT, Message, SYSTEM_PROMPT } from "../constants.ts";
import { ALL_TOOLS } from "../harness/tools/all-tools.ts";
import { Tool, TOOL_CALL_REGEX } from "../harness/tools/tool.ts";

/** skims string for tool calls and returns instance of respective tools */
export function extractTools(
  content: string,
  availableTools = ALL_TOOLS,
): Tool<any>[] {
  const tools: Tool<any>[] = [];

  const calls = [...content.matchAll(TOOL_CALL_REGEX)];

  for (const [_, id, args] of calls) {
    const tool = availableTools.find((tool) => tool.id === id);

    if (!tool) {
      console.warn(`tried to invoke unlisted tool ${id} with ${args}`);
      continue;
    }

    tools.push(...tool.fromArgs(args));
  }

  return tools;
}

import { generateText, LanguageModel } from "ai";
import { Message } from "../constants.ts";
import { convertToStructuredMessage } from "../coder/conversations.ts";
import { extractTools } from "../coder/tools.ts";
import { Logger } from "../coder/logger.ts";

/** Prompts LLM with respect to conversation history and available tools */
export async function feed(
  conversation: Message[],
  model: LanguageModel,
): Promise<Message[]> {
  const prompt = Logger.stringifyConversation(conversation);

  try {
    const { text } = await generateText({
      model,
      prompt,
    });

    const responseConversation = [];
    responseConversation.push(convertToStructuredMessage("model", text));

    const tools = extractTools(text);

    for await (const tool of tools) {
      const results = await tool.call();

      responseConversation.push(...results);
    }

    if (responseConversation.length > 1) {
      const followUp = await feed(
        [...conversation, ...responseConversation],
        model,
      );

      responseConversation.push(...followUp);
    }

    return responseConversation;
  } catch (e) {
    console.error(e);

    return [];
  }
}

import { createGoogleGenerativeAI } from "@ai-sdk/google";

const AI_STUDIO_API_KEY = Deno.env.get("AI_STUDIO_API_KEY");

const google = createGoogleGenerativeAI({
  apiKey: AI_STUDIO_API_KEY,
});

export const GEMINI_3_FLASH_PREVIEW = google("gemini-3-flash-preview");

export const GEMINI_3_1_FLASH_LITE_PREVIEW = google(
  "gemini-3.1-flash-lite-preview",
);

export const GEMINI_3_1_PRO_PREVIEW = google("gemini-3.1-pro-preview");

import { LanguageModel } from "ai";
import { Message, SYSTEM_PROMPT } from "../constants.ts";
import { feed } from "./feed.ts";
import { convertToStructuredMessage } from "../coder/conversations.ts";

export class Session {
  public readonly id: string;
  private conversation: Message[] = [
    SYSTEM_PROMPT,
  ];
  private model: LanguageModel;

  constructor(
    model: LanguageModel,
  ) {
    this.id = crypto.randomUUID();
    this.model = model;

    Deno.mkdirSync("./chats", { recursive: true });
    this.saveSync();
  }

  private saveSync(): void {
    Deno.writeTextFileSync(
      `./chats/${this.id}.json`,
      JSON.stringify(this.conversation, null, 2),
    );
  }

  private async save(): Promise<void> {
    await Deno.writeTextFile(
      `./chats/${this.id}.json`,
      JSON.stringify(this.conversation, null, 2),
    );
  }

  async prompt(content: string): Promise<Message[]> {
    const message = convertToStructuredMessage("user", content);
    this.conversation.push(message);
    await this.save();

    const responses = await feed(this.conversation, this.model);
    this.conversation.push(...responses);
    await this.save();

    return responses;
  }
}

import { ListDir } from "./list-dir.ts";
import { ListTools } from "./list-tools.ts";
import { ReadFile } from "./read-file.ts";
import { Tool } from "./tool.ts";
import { WriteFile } from "./write-file.ts";

export const ALL_TOOLS: (typeof Tool<any>)[] = [
  ListTools,
  ReadFile,
  ListDir,
  WriteFile,
];

import { convertToStructuredMessage } from "../../coder/conversations.ts";
import { Message } from "../../constants.ts";
import { Tool } from "./tool.ts";

const DESCRIPTION =
  `The "list-dir" tool can be used to list the contents of a directory provided its path.
Bulk operations are possible, one can supply multiple directory paths to get the contents at once.

To invoke, respond in the form of {"tool":"list-dir","args":string[]} where the string array are
the paths to requested directories. Absolute as well as relative directory paths are possible.`;

export class ListDir extends Tool<[string]> {
  static override id = "list-dir";

  static override description = DESCRIPTION;

  static override matchesToolInvocation(content: string): boolean {
    const regex =
      /\{\s*"?tool"?\s*:\s*"list-dir"\s*,\s*"?args"?\s*:\s*\[[^\]]*\]\s*\}/;

    return regex.test(content);
  }

  static override fromArgs(args: string): ListDir[] {
    const paths = JSON.parse(args) as string[];
    return paths.map((path) => new ListDir(path));
  }

  constructor(private path: string) {
    super(path);
  }

  override async call(): Promise<Message[]> {
    try {
      const entries: string[] = [];

      for await (const dirEntry of Deno.readDir(this.path)) {
        let suffix = "";
        if (dirEntry.isDirectory) suffix = "/";
        else if (dirEntry.isSymlink) suffix = "@";

        entries.push(`${dirEntry.name}${suffix}`);
      }

      // Sort alphabetically for readability
      entries.sort();

      const content = entries.length > 0
        ? entries.join("\n")
        : "(empty directory)";

      return [
        convertToStructuredMessage(
          "system",
          `Contents of ${this.path}:\n${content}`,
        ),
      ];
    } catch (e) {
      console.log(e);

      const errorMessage = e instanceof Error ? e.message : String(e);
      return [
        convertToStructuredMessage(
          "system",
          `Error reading directory ${this.path}: ${errorMessage}`,
        ),
      ];
    }
  }
}

import { convertToStructuredMessage } from "../../coder/conversations.ts";
import { Message } from "../../constants.ts";
import { ALL_TOOLS } from "./all-tools.ts";
import { Tool } from "./tool.ts";

const DESCRIPTION =
  `The "list-tools" tool can be used to list all tools available. It returns the description
of all tools, explaining what they are used for, and what there syntax is.

To invoke, respond in the form of {tool:"list-tools",args:""}. No arguments other then "" are possible.`;

export class ListTools extends Tool<[]> {
  static override id = "list-tools";

  static override description = DESCRIPTION;

  static override matchesToolInvocation(content: string): boolean {
    const regex =
      /\{\s*"?tool"?\s*:\s*"list-tools"\s*,\s*"?args"?\s*:\s*""\s*\}/;

    return regex.test(content);
  }

  static override fromArgs(args: string): ListTools[] {
    return [new ListTools()];
  }

  override async call(): Promise<Message[]> {
    const content = ALL_TOOLS.map((tool, i) =>
      `Tool ${tool.id} -- ${i + 1}/${ALL_TOOLS.length}
  ${tool.description}`
    ).join("\n");

    return [convertToStructuredMessage("system", content)];
  }
}

import { convertToStructuredMessage } from "../../coder/conversations.ts";
