import { Tool } from "./tool.ts";

const DESCRIPTION =
  `The "read-file" tool can be used to read the contents of any file provided its path.
Bulk operations are possible, one can supply multiple file paths to get the contents at once.

To invoke, respond in the form of {tool:"read-file",args:string[]} where the string array are
the paths to requested files. Absolute as well as relative file paths are possible.`;

export class ReadFile extends Tool<[string]> {
  static override id = "read-file";

  static override description = DESCRIPTION;

  static override matchesToolInvocation(content: string): boolean {
    const regex =
      /\{\s*"?tool"?\s*:\s*"read-file"\s*,\s*"?args"?\s*:\s*\[[^\]]*\]\s*\}/;

    return regex.test(content);
  }

  static override fromArgs(args: string): ReadFile[] {
    const paths = JSON.parse(args) as string[];
    return paths.map((path) => new ReadFile(path));
  }

  constructor(private path: string) {
    super(path);
  }

  override async call(): Promise<Message[]> {
    const decoder = new TextDecoder();

    try {
      const file = await Deno.readFile(this.path);
      const content = decoder.decode(file);

      return [convertToStructuredMessage("system", content)];
    } catch (e) {
      console.log(e);

      const errorMessage = e instanceof Error ? e.message : String(e);
      return [
        convertToStructuredMessage(
          "system",
          `Error reading file ${this.path}: ${errorMessage}`,
        ),
      ];
    }
  }
}

import { Message } from "../../constants.ts";

export const TOOL_CALL_REGEX =
  /\{\s*"?tool"?\s*:\s*"([^"]+)"\s*,\s*"?args"?\s*:\s*("(?:\\.|[^"\\])*"|\[[\s\S]*?\]|\{[\s\S]*?\}|[^}\s]+)\s*\}/g;

export abstract class Tool<Args extends unknown[]> {
  static id: string;

  static description: string;

  static matchesToolInvocation(_content: string): boolean {
    throw new Error("`matchesToolInvocation` not implemented");
  }

  static fromArgs(_args: string): Tool<any>[] {
    throw new Error("`fromArgs` not implemented");
  }

  readonly args: Args;

  constructor(...args: Args) {
    this.args = args;
  }

  get meta(): { id: string; args: Args } {
    const ctor = this.constructor as typeof Tool;

    return {
      id: ctor.id,
      args: this.args,
    };
  }

  async call(): Promise<Message[]> {
    throw new Error("`call` is not implemented");
  }
}

import { convertToStructuredMessage } from "../../coder/conversations.ts";
import { Message } from "../../constants.ts";
import { Tool } from "./tool.ts";

const DESCRIPTION =
  `The "write-file" tool can be used to create new files or overwrite existing files with provided content.
It acts on one file at a time.

To invoke, respond in the form of {"tool":"write-file","args":{"path":"string","content":"string"}} where path is the target file path and content is the string content to write. Absolute as well as relative file paths are possible.`;

export class WriteFile extends Tool<[string, string]> {
  static override id = "write-file";

  static override description = DESCRIPTION;

  static override matchesToolInvocation(content: string): boolean {
    const regex =
      /\{\s*"?tool"?\s*:\s*"write-file"\s*,\s*"?args"?\s*:\s*\{[\s\S]*?\}\s*\}/;

    return regex.test(content);
  }

  static override fromArgs(args: string): WriteFile[] {
    const parsed = JSON.parse(args) as { path: string; content: string };
    return [new WriteFile(parsed.path, parsed.content)];
  }

  constructor(private path: string, private content: string) {
    super(path, content);
  }

  override async call(): Promise<Message[]> {
    try {
      await Deno.writeTextFile(this.path, this.content);

      return [
        convertToStructuredMessage(
          "system",
          `Successfully wrote to ${this.path}`,
        ),
      ];
    } catch (e) {
      console.log(e);

      const errorMessage = e instanceof Error ? e.message : String(e);
      return [
        convertToStructuredMessage(
          "system",
          `Error writing file ${this.path}: ${errorMessage}`,
        ),
      ];
    }
  }
}
